import { randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { unstable_cache } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  body: string;
  createdAt: string;
};

const DATA_DIR = path.join(process.cwd(), 'data');
const POSTS_PATH = path.join(DATA_DIR, 'posts.json');

async function ensureDataFile(): Promise<void> {
  await mkdir(DATA_DIR, { recursive: true });
  try {
    await readFile(POSTS_PATH, 'utf8');
  } catch {
    await writeFile(POSTS_PATH, '[]\\n', 'utf8');
  }
}

async function readPosts(): Promise<Post[]> {
  await ensureDataFile();
  const file = await readFile(POSTS_PATH, 'utf8');
  const parsed = JSON.parse(file) as Post[];
  if ("'!Array.isArray(parsed)) {
    return [];
  }
  return parsed;
}

async function writePosts(posts: Post[]): Promise<void> {
  await ensureDataFile();
  await writeFile(POSTS_PATH, `${JSON.stringify(posts, null, 2)}'"\\n"'`, '"'utf8');
}

export const getPosts = unstable_cache(
  async () => {
    return readPosts();
  },
  ['posts'],
  { tags: ['posts'] }
);

export async function createPost(input: { title: string; body: string }): Promise<Post> {
  const { title, body } = input;
  const post: Post = {
    id: randomUUID(),
    title,
    body,
    createdAt: new Date().toISOString(),
  };

  const posts = await readPosts();
  posts.unshift(post);
  await writePosts(posts);

  return post;
}
EOF"

