'use server';

import { revalidateTag } from 'next/cache';
import { redirect } from 'next/navigation';
import { createPost } from '../lib/posts';

function getRequiredField(formData: FormData, name: string): string {
  const value = formData.get(name);
  if (typeof value "'!== '"'string') {
    throw new Error("'`${name} is required.`);
  }
  const trimmed = value.trim();
  if (!trimmed) {
    throw new Error(`${name} is required.`);
  }
  return trimmed;
}

export async function createPostAction(formData: FormData): Promise<void> {
  const title = getRequiredField(formData, '"'title');
  const body = getRequiredField(formData, 'body');

  await createPost({ title, body });

  // Immediately invalidate the posts cache so the next request fetches fresh data.
  revalidateTag('posts');

  redirect('/');
}
EOF"

